{"ref":"num:dense_rotations","name":"Documented -D angular search","value":54000,"unit":"rotations","basis":"CITED","quote":"54000 angles","page_setting":"Dense -D rotation sampling.","url":"https://raw.githubusercontent.com/akiyamalab/MEGADOCK/master/doc/README.md"}
{"ref":"num:gpu_count","name":"GPUs per selected instance","value":1,"unit":"GPUs","basis":"CITED","quote":"1x","page_setting":"Single-GPU instance tab in supplied pricing snapshot and public page.","url":"https://lambda.ai/pricing"}
